<template>
  <div class="report-view bg-light min-vh-100">
    <NavBarVue />

    <b-container fluid class="py-4">
      <b-row class="justify-content-center">
        <b-col lg="11">
          <!-- Cabeçalho -->
          <b-card no-body class="border-0 shadow-sm mb-4">
            <b-card-body class="p-4">
              <b-row align-v="center">
                <b-col lg="3" class="mb-3 mb-lg-0">
                  <h4 class="text-dark font-weight-bold mb-1">
                    <b-icon icon="journal-text" class="text-mbr-green mr-2"></b-icon>
                    Logs do Sistema
                  </h4>
                  <p class="text-muted small mb-0">
                    Rastreio de atividades e segurança
                  </p>
                </b-col>

                <b-col lg="9">
                  <b-row class="align-items-end justify-content-end">
                    <b-col sm="3" class="mb-2 mb-sm-0">
                      <label class="small font-weight-bold text-secondary">Início</label>
                      <b-form-datepicker
                        v-model="fromDate"
                        size="sm"
                        locale="pt-PT"
                        placeholder="Data inicial"
                        class="border-0 bg-light"
                        today-button
                        reset-button
                        @input="getSystemLogs()"
                      ></b-form-datepicker>
                    </b-col>
                    <b-col sm="3" class="mb-2 mb-sm-0">
                      <label class="small font-weight-bold text-secondary">Fim</label>
                      <b-form-datepicker
                        v-model="toDate"
                        size="sm"
                        locale="pt-PT"
                        placeholder="Data final"
                        class="border-0 bg-light"
                        today-button
                        reset-button
                        @input="getSystemLogs()"
                      ></b-form-datepicker>
                    </b-col>
                    <b-col sm="4" class="mb-2 mb-sm-0">
                      <label class="small font-weight-bold text-secondary">Pesquisar</label>
                      <b-input-group size="sm">
                        <b-form-input
                          v-model="searchQuery"
                          placeholder="Utilizador, operação ou descrição..."
                          class="border-0 bg-light"
                          debounce="300"
                        ></b-form-input>
                        <b-input-group-append v-if="searchQuery">
                          <b-button variant="outline-secondary" size="sm" @click="searchQuery = ''">
                            <b-icon icon="x"></b-icon>
                          </b-button>
                        </b-input-group-append>
                      </b-input-group>
                    </b-col>
                    <b-col sm="auto">
                      <b-button
                        variant="mbr-green"
                        @click="getSystemLogs()"
                        :disabled="loading"
                        size="sm"
                        class="px-4 shadow-sm"
                      >
                        <b-icon icon="arrow-clockwise" v-if="!loading" class="mr-1"></b-icon>
                        <b-spinner small v-else></b-spinner>
                        Actualizar
                      </b-button>
                    </b-col>
                  </b-row>
                </b-col>
              </b-row>
            </b-card-body>
          </b-card>

          <!-- Tabela de Logs -->
          <b-card no-body class="border-0 shadow-sm overflow-hidden">
            <b-card-header class="bg-white border-0 py-3 d-flex justify-content-between align-items-center">
              <h6 class="mb-0 font-weight-bold text-muted">
                Registos encontrados: <b class="text-dark">{{ filteredLogs.length }}</b>
                <span v-if="searchQuery" class="text-muted font-weight-normal">
                  (filtrado de {{ localLogs.length }})
                </span>
              </h6>
              <b-button-group size="sm">
                <b-button
                  variant="outline-danger"
                  @click="downloadSystemLogsPDF()"
                  :disabled="filteredLogs.length === 0"
                >
                  <b-icon icon="file-earmark-pdf-fill"></b-icon> PDF
                </b-button>
                <b-button
                  variant="outline-success"
                  @click="downloadSystemLogsExcel()"
                  :disabled="filteredLogs.length === 0"
                >
                  <b-icon icon="file-earmark-excel-fill"></b-icon> Excel
                </b-button>
              </b-button-group>
            </b-card-header>

            <b-overlay :show="loading" rounded="sm" opacity="0.6">
              <div class="table-responsive">
                <table class="table table-hover mb-0">
                  <thead class="bg-mbr-light text-mbr-green small text-uppercase font-weight-bold">
                    <tr>
                      <th class="border-0 pl-4" style="width: 160px">Data e Hora</th>
                      <th class="border-0" style="width: 180px">Utilizador</th>
                      <th class="border-0" style="width: 180px">Operação</th>
                      <th class="border-0">Detalhes da Atividade</th>
                    </tr>
                  </thead>
                  <tbody class="text-secondary">
                    <tr v-for="log in paginatedLogs" :key="log.id">
                      <td class="pl-4 align-middle">
                        <div class="d-flex flex-column">
                          <span class="text-dark font-weight-bold">{{ formatDate(log.createdAt) }}</span>
                          <small class="text-muted">{{ formatTime(log.createdAt) }}</small>
                        </div>
                      </td>
                      <td class="align-middle">
                        <div class="d-flex align-items-center">
                          <b-avatar size="1.4rem" variant="light" class="mr-2"></b-avatar>
                          <span class="font-weight-500">{{ log.userName }}</span>
                        </div>
                      </td>
                      <td class="align-middle">
                        <b-badge :variant="getActionVariant(log.action)" pill class="px-3 py-1">
                          {{ log.action || 'N/A' }}
                        </b-badge>
                      </td>
                      <td class="align-middle small py-3" style="max-width: 400px; line-height: 1.4">
                        {{ log.description }}
                      </td>
                    </tr>

                    <tr v-if="filteredLogs.length === 0 && !loading">
                      <td colspan="4" class="text-center py-5">
                        <b-icon icon="inbox" font-scale="3" class="text-muted mb-2 d-block mx-auto"></b-icon>
                        <p class="text-muted mb-0" v-if="searchQuery">
                          Nenhum resultado para "<strong>{{ searchQuery }}</strong>".
                        </p>
                        <p class="text-muted mb-0" v-else-if="localLogs.length === 0">
                          Nenhum log encontrado para o período seleccionado.
                        </p>
                      </td>
                    </tr>
                  </tbody>
                </table>
              </div>

              <!-- Paginação -->
              <div
                v-if="totalPages > 1"
                class="d-flex justify-content-between align-items-center px-4 py-3 border-top"
              >
                <small class="text-muted">
                  Mostrando {{ startIndex + 1 }}–{{ endIndex }} de {{ filteredLogs.length }} registos
                </small>
                <b-pagination
                  v-model="currentPage"
                  :total-rows="filteredLogs.length"
                  :per-page="perPage"
                  size="sm"
                  class="mb-0"
                  first-number
                  last-number
                  limit="5"
                ></b-pagination>
                <b-form-select
                  v-model="perPage"
                  :options="perPageOptions"
                  size="sm"
                  style="width: 80px"
                  @change="currentPage = 1"
                ></b-form-select>
              </div>
            </b-overlay>
          </b-card>
        </b-col>
      </b-row>
    </b-container>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import axios from "axios";
import DateFormat from "../utils/dateFormat";
import NavBarVue from "@/components/NavBar";
import exportFromJSON from "export-from-json";
import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
pdfMake.vfs = pdfFonts.pdfMake.vfs;

export default {
  name: "SystemLogsView",
  components: { NavBarVue },

  data: () => ({
    fromDate: "",
    toDate: "",
    searchQuery: "",
    localLogs: [],
    loading: false,
    currentPage: 1,
    perPage: 20,
    perPageOptions: [
      { value: 10, text: "10" },
      { value: 20, text: "20" },
      { value: 50, text: "50" },
      { value: 100, text: "100" },
    ],
  }),

  created() {
    this.getSystemLogs();
  },

  computed: {
    ...mapGetters(["user", "company"]),

    filteredLogs() {
      if (!this.searchQuery) return this.localLogs;

      const query = this.searchQuery.toLowerCase();
      return this.localLogs.filter((log) => {
        const userName = (log.userName || "").toLowerCase();
        const action = (log.action || "").toLowerCase();
        const description = (log.description || "").toLowerCase();
        return (
          userName.includes(query) ||
          action.includes(query) ||
          description.includes(query)
        );
      });
    },

    totalPages() {
      return Math.ceil(this.filteredLogs.length / this.perPage);
    },

    startIndex() {
      return (this.currentPage - 1) * this.perPage;
    },

    endIndex() {
      return Math.min(this.startIndex + this.perPage, this.filteredLogs.length);
    },

    paginatedLogs() {
      return this.filteredLogs.slice(this.startIndex, this.endIndex);
    },
  },

  watch: {
    searchQuery() {
      this.currentPage = 1;
    },
  },

  methods: {
    getSystemLogs() {
      this.loading = true;
      const params = {};
      if (this.fromDate) params.from = this.fromDate;
      if (this.toDate) params.to = this.toDate;

      axios
        .get(`/api/logs/${this.user.companyId}`, { params })
        .then((res) => {
          const data = res.data;
          if (data && data.success && Array.isArray(data.result)) {
            this.localLogs = data.result;
          } else {
            this.localLogs = [];
          }
          this.currentPage = 1;
        })
        .catch((err) => {
          console.error("Erro ao carregar logs:", err);
          this.showToast("Erro!", "danger", "Não foi possível carregar os logs.");
          this.localLogs = [];
        })
        .finally(() => {
          this.loading = false;
        });
    },

    formatDate(date) {
      return DateFormat.formatDate(date);
    },

    formatTime(date) {
      return new Date(date).toLocaleTimeString("pt-PT", {
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit",
      });
    },

    getActionVariant(action) {
      if (!action) return "light";
      const a = action.toLowerCase();
      if (a.includes("login") || a.includes("autenticação")) return "soft-info";
      if (a.includes("delete") || a.includes("remover") || a.includes("eliminar")) return "soft-danger";
      if (a.includes("update") || a.includes("editar") || a.includes("actualizar")) return "soft-warning";
      if (a.includes("create") || a.includes("cadastro") || a.includes("criar") || a.includes("desembolso") || a.includes("pagamento")) return "soft-success";
      return "light";
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(msg, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },

    downloadSystemLogsPDF() {
      const body = this.filteredLogs.map((log) => [
        { text: DateFormat.formatDate(log.createdAt), fontSize: 8 },
        { text: log.userName || "", fontSize: 8 },
        { text: log.action || "", fontSize: 8 },
        { text: log.description || "", fontSize: 7 },
      ]);

      const docDefinition = {
        content: [
          {
            text: `${this.company.companyName || "MICROCRÉDITO"} - RELATÓRIO DE AUDITORIA`,
            style: "header",
          },
          {
            text: `Período: ${this.fromDate || "Início"} até ${this.toDate || "Hoje"} | Total: ${this.filteredLogs.length} registos`,
            margin: [0, 5, 0, 15],
            fontSize: 9,
          },
          {
            table: {
              headerRows: 1,
              widths: ["auto", "auto", "auto", "*"],
              body: [
                [
                  { text: "Data", style: "tableHeader" },
                  { text: "Utilizador", style: "tableHeader" },
                  { text: "Acção", style: "tableHeader" },
                  { text: "Descrição", style: "tableHeader" },
                ],
                ...body,
              ],
            },
            layout: "lightHorizontalLines",
          },
        ],
        styles: {
          header: { fontSize: 14, bold: true, color: "#009640" },
          tableHeader: {
            bold: true,
            fontSize: 9,
            color: "white",
            fillColor: "#009640",
          },
        },
      };
      pdfMake.createPdf(docDefinition).open();
    },

    downloadSystemLogsExcel() {
      const data = this.filteredLogs.map((log) => ({
        Data: DateFormat.formatDate(log.createdAt),
        Hora: this.formatTime(log.createdAt),
        Utilizador: log.userName || "",
        Acção: log.action || "",
        Descrição: log.description || "",
      }));
      exportFromJSON({
        data,
        fileName: "Logs_Auditoria",
        exportType: "xls",
      });
    },
  },
};
</script>

<style scoped>
.text-mbr-green {
  color: #009640 !important;
}
.bg-mbr-green {
  background-color: #009640 !important;
}
.bg-mbr-light {
  background-color: #f0f9f4;
}

.btn-mbr-green {
  background-color: #009640;
  color: white;
  border: none;
  transition: all 0.3s;
}
.btn-mbr-green:hover {
  background-color: #007a33;
  transform: translateY(-1px);
}

/* VARIANTES DE BADGE SUAVES */
.badge-soft-info {
  background-color: #e0f2fe;
  color: #0369a1;
}
.badge-soft-success {
  background-color: #dcfce7;
  color: #15803d;
}
.badge-soft-warning {
  background-color: #fef9c3;
  color: #a16207;
}
.badge-soft-danger {
  background-color: #fee2e2;
  color: #b91c1c;
}

.font-weight-500 {
  font-weight: 500;
}

.table-hover tbody tr:hover {
  background-color: rgba(0, 150, 64, 0.02);
}
</style>
